const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const dir = process.cwd();
const payloadPath = path.join(dir, 'payload.txt');
const flagPath = path.join(dir, 'ready.flag');

const child = spawn(process.execPath, ['service.js'], { cwd: dir, stdio: 'ignore' });

const start = Date.now();
const TIMEOUT = 5000;
let done = false;

function finish(code) {
  if (done) return;
  done = true;
  clearInterval(timer);
  try { child.kill(); } catch (e) {}
  process.exit(code);
}

const timer = setInterval(() => {
  const waited = Date.now() - start;
  if (fs.existsSync(flagPath) && fs.existsSync(payloadPath)) {
    const payload = fs.readFileSync(payloadPath, 'utf8');
    console.log(JSON.stringify({ waitedMs: waited, payload }));
    console.log('DONE: ok');
    finish(0);
    return;
  }
  if (waited >= TIMEOUT) {
    console.error('timeout waiting for ready.flag/payload.txt');
    finish(1);
  }
}, 20);

